20	    private static void quickSort(int[] values, int left, int right) {
21	        while (right - left > INSERTION_SORT_THRESHOLD) {
22	            int pivotIndex = partition(values, left, right);
23	
24	            if (pivotIndex - left < right - pivotIndex) {
25	                quickSort(values, left, pivotIndex - 1);
26	                left = pivotIndex + 1;
27	            } else {
28	                quickSort(values, pivotIndex + 1, right);
29	                right = pivotIndex - 1;
30	            }
31	        }
32	
33	        insertionSort(values, left, right);
34	    }
35	
36	    private static int partition(int[] values, int left, int right) {
37	        int pivotIndex = medianOfThree(values, left, right);
38	        int pivot = values[pivotIndex];
39	        swap(values, pivotIndex, right);
40	
41	        int storeIndex = left - 1;
42	
43	        for (int index = left; index < right; index++) {
44	            if (values[index] < pivot) {
45	                storeIndex++;
46	                swap(values, storeIndex, index);
47	            }
48	        }
49	
50	        swap(values, storeIndex + 1, right);
51	        return storeIndex + 1;
52	    }
53	
54	    private static int medianOfThree(int[] values, int left, int right) {
55	        int middle = left + ((right - left) >>> 1);
56	
57	        if (values[left] > values[middle]) {
58	            swap(values, left, middle);
59	        }
60	        if (values[left] > values[right]) {
61	            swap(values, left, right);
62	        }
63	        if (values[middle] > values[right]) {
64	            swap(values, middle, right);
65	        }
66	
67	        return middle;
68	    }
69	
70	    private static void insertionSort(int[] values, int left, int right) {
71	        for (int index = left + 1; index <= right; index++) {
72	            int currentValue = values[index];
73	            int position = index - 1;
74	
75	            while (position >= left && values[position] > currentValue) {
76	                values[position + 1] = values[position];
77	                position--;
78	            }
79	
80	            values[position + 1] = currentValue;
81	        }
82	    }
83	
84	    private static void swap(int[] values, int first, int second) {
85	        int temp = values[first];
86	        values[first] = values[second];
87	        values[second] = temp;
88	    }
